use anyhow::{Context, Result, ensure};
use rustix::fs::{Dir, FileType, Mode, OFlags, open, openat};
use std::fs::{File, Metadata};
use std::io;
use std::os::unix::fs::MetadataExt;
use std::path::Path;
use std::sync::Arc;

/// One piece of a composed file, in presentation order.
pub enum Piece {
    /// Bytes generated by the plugin.
    Bytes(Vec<u8>),
    /// A byte range of the source file being presented.
    Own { offset: u64, length: u64 },
    /// A byte range of a regular file under another read-only source.
    /// With `stamp`, the file is not opened while the layout is built; the
    /// stamp is checked against the real file on every read instead.
    Other {
        source: Arc<Source>,
        /// Path relative to `source`, components joined by `/`. Shared so a
        /// plugin can hand out the same string for every layout it builds.
        path: Arc<str>,
        offset: u64,
        length: u64,
        stamp: Option<Stamp>,
    },
}

/// Application policy. The transport owns every source descriptor and enforces
/// read-only, no-symlink access independently of plugin decisions.
pub trait Plugin: Send + Sync {
    fn identity(&self) -> Option<String> {
        None
    }
    fn visible(&self, _parts: &[String], _metadata: &Metadata) -> Result<bool> {
        Ok(true)
    }
    fn mtime(&self, _parts: &[String], metadata: &Metadata) -> Result<i64> {
        Ok(metadata.mtime())
    }
    /// Present a regular file as a sequence of pieces instead of its own bytes.
    /// `None` presents the file unchanged. Must be deterministic for a session.
    fn compose(&self, _parts: &[String], _file: &File) -> Result<Option<Vec<Piece>>> {
        Ok(None)
    }
    /// A client changed or created `parts`; `file` holds its new contents.
    /// Called by writable transports (NFS) and by harvests of writable
    /// mounts. The source tree itself is never written. Default: ignore.
    fn written(&self, _parts: &[String], _file: &File) -> Result<()> {
        Ok(())
    }
}

/// A file identity captured when a layout is built; reads fail if it changes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Stamp {
    pub size: u64,
    pub mtime: i64,
    pub nsec: i64,
}
impl Stamp {
    pub fn of(file: &File) -> io::Result<Self> {
        let m = file.metadata()?;
        Ok(Self {
            size: m.len(),
            mtime: m.mtime(),
            nsec: m.mtime_nsec(),
        })
    }
}

/// A validated piece: every file range is within its captured file.
pub(crate) enum Resolved {
    Bytes(Box<[u8]>),
    /// A range of the presented file itself.
    Own {
        stamp: Stamp,
        offset: u64,
        length: u64,
    },
    /// A range of a file under another source.
    Other {
        source: Arc<Source>,
        path: Arc<str>,
        stamp: Stamp,
        offset: u64,
        length: u64,
    },
}
impl Resolved {
    pub fn length(&self) -> u64 {
        match self {
            Self::Bytes(b) => b.len() as u64,
            Self::Own { length, .. } | Self::Other { length, .. } => *length,
        }
    }
}

/// Split a `/`-joined relative path into checked components.
pub(crate) fn split_path(path: &str) -> Vec<String> {
    path.split('/').map(str::to_owned).collect()
}
pub struct Passthrough;
impl Plugin for Passthrough {}

pub struct Source {
    root: File,
}
fn ro_flags() -> OFlags {
    OFlags::RDONLY | OFlags::NOFOLLOW | OFlags::NONBLOCK | OFlags::CLOEXEC
}
impl Source {
    pub fn new(root: &Path) -> Result<Self> {
        Ok(Self {
            root: File::from(open(root, ro_flags() | OFlags::DIRECTORY, Mode::empty())?),
        })
    }
    pub fn open_raw(&self, parts: &[String]) -> Result<File> {
        let mut file = File::from(openat(
            &self.root,
            ".",
            ro_flags() | OFlags::DIRECTORY,
            Mode::empty(),
        )?);
        for (i, part) in parts.iter().enumerate() {
            ensure!(
                !part.is_empty() && part != "." && part != ".." && !part.contains(['/', '\0']),
                "invalid path component"
            );
            let flags = ro_flags()
                | if i + 1 < parts.len() {
                    OFlags::DIRECTORY
                } else {
                    OFlags::empty()
                };
            file = File::from(openat(&file, part.as_str(), flags, Mode::empty())?);
        }
        let meta = file.metadata()?;
        if !(meta.is_file() || meta.is_dir()) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "only regular files and directories are exposed",
            )
            .into());
        }
        Ok(file)
    }
    /// Open one entry of an already-open directory with the same checks as `open_raw`.
    pub fn open_child(&self, directory: &File, name: &str) -> Result<File> {
        ensure!(
            !name.is_empty() && name != "." && name != ".." && !name.contains(['/', '\0']),
            "invalid path component"
        );
        let file = File::from(openat(directory, name, ro_flags(), Mode::empty())?);
        let meta = file.metadata()?;
        if !(meta.is_file() || meta.is_dir()) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "only regular files and directories are exposed",
            )
            .into());
        }
        Ok(file)
    }
    /// Sorted names with a directory hint from the directory entry type
    /// (`None` when the filesystem does not report it). Symlinks and special
    /// files are omitted; they are never exposed.
    pub fn entries(&self, directory: &File) -> Result<Vec<(String, Option<bool>)>> {
        let mut out = Vec::new();
        for entry in Dir::read_from(directory)? {
            let entry = entry?;
            let name = entry
                .file_name()
                .to_str()
                .context("non-UTF-8 source filename")?;
            if name == "." || name == ".." {
                continue;
            }
            let kind = match entry.file_type() {
                FileType::Directory => Some(true),
                FileType::RegularFile => Some(false),
                FileType::Unknown => None,
                _ => continue,
            };
            out.push((name.to_owned(), kind));
        }
        out.sort();
        Ok(out)
    }
    pub fn names(&self, directory: &File) -> Result<Vec<String>> {
        let mut names = Vec::new();
        for entry in Dir::read_from(directory)? {
            let entry = entry?;
            let name = entry
                .file_name()
                .to_str()
                .context("non-UTF-8 source filename")?;
            if name != "." && name != ".." {
                names.push(name.to_owned());
            }
        }
        names.sort();
        Ok(names)
    }
}

pub struct View {
    source: Arc<Source>,
    plugin: Arc<dyn Plugin>,
    pub(crate) label: String,
}
pub(crate) struct Meta {
    pub directory: bool,
    pub size: u64,
    pub mtime: i64,
    /// Source identity, for the WebDAV entity tag.
    pub ino: u64,
    pub stamp: Stamp,
    /// The file's presented layout; directories have none.
    pub layout: Vec<Resolved>,
}
impl Meta {
    pub fn etag(&self) -> String {
        format!(
            "\"{:x}-{:x}-{:x}-{:x}-{:x}\"",
            self.ino, self.stamp.size, self.stamp.mtime, self.stamp.nsec, self.size
        )
    }
}
pub fn validate_label(label: &str) -> Result<()> {
    ensure!(
        !label.is_empty()
            && label.encode_utf16().count() <= 11
            && !label.contains(['\0', '/', '\\']),
        "volume label must be 1–11 UTF-16 code units without slashes or NUL"
    );
    Ok(())
}
impl View {
    pub fn new(source: Arc<Source>, plugin: Arc<dyn Plugin>, label: String) -> Result<Self> {
        validate_label(&label)?;
        Ok(Self {
            source,
            plugin,
            label,
        })
    }
    pub(crate) fn identity(&self) -> Result<String> {
        if let Some(id) = self.plugin.identity() {
            return Ok(id);
        }
        let meta = self.source.root.metadata()?;
        Ok(format!("{}:{}", meta.dev(), meta.ino()))
    }
    pub(crate) fn open_raw(&self, parts: &[String]) -> Result<File> {
        self.source.open_raw(parts)
    }
    pub(crate) fn open(&self, parts: &[String]) -> Result<File> {
        let file = self.open_raw(parts)?;
        if !self.plugin.visible(parts, &file.metadata()?)? {
            return Err(io::Error::new(io::ErrorKind::NotFound, "hidden by plugin").into());
        }
        Ok(file)
    }
    pub(crate) fn metadata(&self, parts: &[String], file: &File) -> Result<Meta> {
        let s = file.metadata()?;
        let own = Stamp {
            size: s.len(),
            mtime: s.mtime(),
            nsec: s.mtime_nsec(),
        };
        let mut layout = Vec::new();
        if s.is_file() {
            match self.plugin.compose(parts, file)? {
                None => layout.push(Resolved::Own {
                    stamp: own,
                    offset: 0,
                    length: own.size,
                }),
                Some(pieces) => {
                    for piece in pieces {
                        layout.push(match piece {
                            Piece::Bytes(b) => Resolved::Bytes(b.into()),
                            Piece::Own { offset, length } => {
                                ensure!(
                                    offset.checked_add(length).is_some_and(|e| e <= own.size),
                                    "composed range exceeds source file"
                                );
                                Resolved::Own {
                                    stamp: own,
                                    offset,
                                    length,
                                }
                            }
                            Piece::Other {
                                source,
                                path,
                                offset,
                                length,
                                stamp,
                            } => {
                                let stamp = match stamp {
                                    Some(s) => s,
                                    None => {
                                        let f = source.open_raw(&split_path(&path))?;
                                        ensure!(
                                            f.metadata()?.is_file(),
                                            "other piece is not a file"
                                        );
                                        Stamp::of(&f)?
                                    }
                                };
                                ensure!(
                                    offset.checked_add(length).is_some_and(|e| e <= stamp.size),
                                    "composed range exceeds other file"
                                );
                                Resolved::Other {
                                    source,
                                    path,
                                    stamp,
                                    offset,
                                    length,
                                }
                            }
                        });
                    }
                    layout.retain(|r| r.length() > 0);
                }
            }
        }
        let size = layout.iter().map(Resolved::length).sum();
        Ok(Meta {
            directory: s.is_dir(),
            size: if s.is_dir() { s.len() } else { size },
            mtime: self.plugin.mtime(parts, &s)?,
            ino: s.ino(),
            stamp: own,
            layout,
        })
    }

    /// Open the file behind a resolved piece and check it is unchanged.
    pub(crate) fn open_piece(
        &self,
        source: Option<&Source>,
        parts: &[String],
        stamp: Stamp,
    ) -> io::Result<File> {
        let file = match source {
            None => self.open(parts),
            Some(s) => s.open_raw(parts),
        }
        .map_err(io::Error::other)?;
        if Stamp::of(&file)? != stamp {
            return Err(io::Error::other(
                "source file changed since disk snapshot; detach and restart",
            ));
        }
        Ok(file)
    }
    /// Report a client write to the plugin.
    pub(crate) fn written(&self, parts: &[String], file: &File) -> Result<()> {
        self.plugin.written(parts, file)
    }
    pub(crate) fn names(&self, _parts: &[String], file: &File) -> Result<Vec<String>> {
        self.source.names(file)
    }
    pub(crate) fn entries(&self, file: &File) -> Result<Vec<(String, Option<bool>)>> {
        self.source.entries(file)
    }
    /// Open `parts` (whose last component is in `directory`) and apply visibility.
    pub(crate) fn open_child(&self, parts: &[String], directory: &File) -> Result<File> {
        let file = self
            .source
            .open_child(directory, parts.last().context("missing child name")?)?;
        if !self.plugin.visible(parts, &file.metadata()?)? {
            return Err(io::Error::new(io::ErrorKind::NotFound, "hidden by plugin").into());
        }
        Ok(file)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn arbitrary_tree_is_read_only_and_symlinks_are_rejected() -> Result<()> {
        let temp = tempfile::tempdir()?;
        std::fs::write(temp.path().join("notes.txt"), b"general purpose")?;
        std::os::unix::fs::symlink("/etc/hosts", temp.path().join("escape"))?;
        let source = Arc::new(Source::new(temp.path())?);
        let view = View::new(source, Arc::new(Passthrough), "DiskProxy".into())?;
        assert!(view.open(&["notes.txt".into()]).is_ok());
        assert!(view.open(&["escape".into()]).is_err());
        assert!(view.open(&["..".into(), "etc".into()]).is_err());
        assert!(
            View::new(
                Arc::new(Source::new(temp.path())?),
                Arc::new(Passthrough),
                "label too long".into()
            )
            .is_err()
        );
        Ok(())
    }
}
